% Shared mathematical macros for the Thurston blueprint.

\newtheorem{theorem}{Theorem}[chapter]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\newtheorem{conjecture}[theorem]{Conjecture}

\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}
\newtheorem{example}[theorem]{Example}
\newtheorem{notation}[theorem]{Notation}
\newtheorem{convention}[theorem]{Convention}

\providecommand{\sketch}{\emph{Sketch.}\ }

\newcommand{\R}{\mathbb{R}}
\newcommand{\C}{\mathbb{C}}
\newcommand{\Q}{\mathbb{Q}}
\newcommand{\Z}{\mathbb{Z}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\HH}{\mathbb{H}}
\newcommand{\Sph}{\mathbb{S}}
\newcommand{\M}{\mathcal{M}}
\newcommand{\G}{\mathcal{G}}
\newcommand{\Isom}{\operatorname{Isom}}
\newcommand{\PSL}{\operatorname{PSL}}
\newcommand{\Vol}{\operatorname{Vol}}
\newcommand{\vol}{\operatorname{vol}}
\newcommand{\Area}{\operatorname{Area}}
\newcommand{\inj}{\operatorname{inj}}
\newcommand{\diam}{\operatorname{diam}}
\newcommand{\dist}{\operatorname{dist}}
\newcommand{\Int}{\operatorname{int}}
\newcommand{\id}{\operatorname{id}}
\newcommand{\tr}{\operatorname{tr}}
\newcommand{\supp}{\operatorname{supp}}
\newcommand{\Hom}{\operatorname{Hom}}
\newcommand{\Aut}{\operatorname{Aut}}
\newcommand{\Fix}{\operatorname{Fix}}
\newcommand{\rank}{\operatorname{rank}}
\newcommand{\length}{\operatorname{length}}
\newcommand{\eps}{\varepsilon}
\newcommand{\del}{\delta}
\newcommand{\abs}[1]{\lvert #1\rvert}
\newcommand{\norm}[1]{\lVert #1\rVert}

% Horizon metadata is parsed into the dependency graph and hidden in print.
\providecommand{\dcref}[1]{}
\providecommand{\group}[1]{}
\providecommand{\source}[1]{}
\providecommand{\uses}[1]{}
\providecommand{}{}
